questionvariables.text:
/* Randomize bounds for the uniform temperature distribution */
a : rand([18, 19, 20, 21, 22]);
w : rand([10, 12, 15, 20]);   /* widths with several nice fractions */
b : a + w;

/* Part a: Disjoint probabilities */
offset1 : rand([2, 3, 4]);
c : a + offset1; 
offset2 : rand([2, 3, 4]);
d : b - offset2; 

prob_less_c : (c - a) / w;
prob_greater_d : (b - d) / w;
ta1 : prob_less_c + prob_greater_d;

/* Part b: Inverse probability targets */
target_prob_list : [1/4, 1/3, 1/2, 2/3, 3/4, 1/5, 2/5, 3/5, 4/5];
/* keep only probabilities that give a whole-number temperature t = a + p*w */
target_ok : sublist(target_prob_list, lambda([p], integerp(p*w)));
target_prob_num : rand(target_ok);
target_prob_tex : target_prob_num;

/* Calculate t: (t - a) / w = p  =>  t = a + p * w */
ta2 : a + target_prob_num * w;

/* Distractors for targeted PRT feedback */
ta1_wrong : prob_less_c * prob_greater_d;
ta2_wrong : target_prob_num * w;
